CREATE TABLE IF NOT EXISTS "scheduled_group_calls" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "conversation_id" uuid NOT NULL, "created_by" uuid NOT NULL, "call_type" varchar(12) NOT NULL, "title" varchar(160) NOT NULL, "description" text, "scheduled_at" timestamp with time zone NOT NULL, "status" varchar(16) NOT NULL DEFAULT 'scheduled', "created_at" timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT "scheduled_group_calls_conversation_id_conversations_id_fk" FOREIGN KEY ("conversation_id") REFERENCES "conversations"("id") ON DELETE cascade, CONSTRAINT "scheduled_group_calls_created_by_user_profiles_id_fk" FOREIGN KEY ("created_by") REFERENCES "user_profiles"("id") ON DELETE cascade);
CREATE INDEX IF NOT EXISTS "scheduled_group_calls_conversation_idx" ON "scheduled_group_calls" USING btree ("conversation_id","scheduled_at");